/**
 * Translation dictionaries for the landscaping calculators.
 * English is the source of truth and the fallback for every missing key:
 * a missing translation never renders an empty label or a key name.
 * Calculations never read these strings. Coverage is measured by
 * `dictionaryCoverage` in the test suite and reported in
 * docs/landscaping-calculators.md — never mark a tool complete when
 * its keys are missing in a language.
 */
import type { Locale } from "./landscaping-i18n";

export type Dictionary = Record<string, string>;
export type PluralDict = Record<string, string | { one: string; other: string }>;

export function translate(locale: Locale, dict: Dictionary, fallback: Dictionary, key: string, vars?: Record<string, string | number>): string {
  let text = dict[key] ?? fallback[key] ?? key;
  if (vars) for (const [name, value] of Object.entries(vars)) text = text.split(`{${name}}`).join(String(value));
  return text;
}

export function dictionaryCoverage(dict: Dictionary, fallback: Dictionary): { total: number; present: number; missing: string[] } {
  const keys = Object.keys(fallback);
  const missing = keys.filter(k => !(k in dict));
  return { total: keys.length, present: keys.length - missing.length, missing };
}

