export const dictionaries: Partial<Record<Locale, Dictionary>> = { en };
export function getDictionary(locale: Locale): Dictionary { return dictionaries[locale] ?? en; }
export function t(locale: Locale, key: string, vars?: Record<string, string | number>): string {
  return translate(locale, getDictionary(locale), en, key, vars);
}

